{
  "predictors": [
    {
      "name": "Social Media Sentiment Score",
      "construction": "Aggregate sentiment score from social media mentions related to a stock over the past 30 days. Use a natural language processing algorithm to classify mentions as positive, neutral, or negative.",
      "rationale": "Positive sentiment on social media can drive investor attention and purchasing behavior, leading to higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Activity Index",
      "construction": "Ratio of new patents filed by the company over the past year to total assets. Use patent filing data from the US Patent and Trademark Office.",
      "rationale": "A higher rate of innovation, as indicated by patent filings, may lead to competitive advantages and future growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Efficiency Ratio",
      "construction": "Company's total revenue divided by its carbon emissions footprint over the past fiscal year. Data sourced from environmental reports and financial statements.",
      "rationale": "Firms that generate more revenue per unit of carbon emissions may have a more sustainable business model, attracting environmentally conscious investors.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Average employee satisfaction score based on survey data collected from employee reviews over the past year.",
      "rationale": "High employee satisfaction can lead to higher productivity and lower turnover, positively impacting firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Diversity Score",
      "construction": "Percentage of suppliers from diverse industries relative to total suppliers over the past year as reported in supply chain disclosures.",
      "rationale": "A diverse supply chain can mitigate risks related to supply disruptions and enhance operational stability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Gender Diversity Ratio",
      "construction": "Proportion of female members on the company's board of directors as of the latest fiscal year-end.",
      "rationale": "Diverse perspectives in leadership can lead to better decision-making and governance, potentially enhancing firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Loyalty Index",
      "construction": "Annual change in the number of repeat customers divided by total customer base, based on company-reported sales data.",
      "rationale": "A loyal customer base can provide stable revenues and reduce marketing costs, leading to improved profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Transactions Ratio",
      "construction": "Total insider purchases divided by total insider sales over the past six months, using data from SEC Form 4 filings.",
      "rationale": "Increased insider buying relative to selling may indicate insiders' confidence in the firm's future prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Intellectual Property Intensity",
      "construction": "Company's intangible assets as a percentage of total assets, using the most recent balance sheet data.",
      "rationale": "Higher proportions of intangible assets may indicate a stronger intellectual property portfolio, which can drive future growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Green Investment Ratio",
      "construction": "Expenditure on environmentally sustainable projects divided by total capital expenditure over the past year, based on company financial reports.",
      "rationale": "Investment in sustainable projects can lead to long-term cost savings and compliance with future regulations.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
